export default function App() {
  const [sessionReady,setSessionReady]=useState(false),[authenticated,setAuthenticated]=useState(false),[tab,setTab]=useState<Tab>("home"),[data,setData]=useState<PatientDashboard|null>(null),[catalog,setCatalog]=useState<BookingService[]>([]),[care,setCare]=useState<PatientCareHub>({activePlan:null,history:[],appointmentTracking:[]}),[membership,setMembership]=useState<PatientMembership|null>(null),[results,setResults]=useState<PatientResults>({media:[],recommendations:[]}),[beauty,setBeauty]=useState<BeautyCalendarData>({events:[],contact:null}),[finance,setFinance]=useState<FinanceHealthHub>({wallet:{totalPaid:0,outstanding:0,currency:"SAR",transactions:[]},health:{record:null,completeness:0,updateRequests:[]}}),[experience,setExperience]=useState<PatientExperience>({moments:[],eligibleVisits:[],feedback:[]}),[error,setError]=useState(""),[language,setLanguage]=useState<Language>("en");
  const [toolbarOpacity]=useState(()=>new Animated.Value(1)),toolbarTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
  const fadeToolbar=()=>{if(tab!=="home")return;if(toolbarTimer.current)clearTimeout(toolbarTimer.current);Animated.timing(toolbarOpacity,{toValue:0,duration:280,useNativeDriver:true}).start();toolbarTimer.current=setTimeout(()=>Animated.timing(toolbarOpacity,{toValue:1,duration:320,useNativeDriver:true}).start(),650);};
  const refresh=useCallback(async()=>{try{setError("");const [dashboard,booking,careHub,membershipCard,patientResults,beautyCalendar,financeHealth,patientExperience]=await Promise.all([loadDashboard(),loadBookingCatalog(),loadCareHub(),loadMembership(),loadPatientResults(),loadBeautyCalendar(),loadFinanceHealth(),loadPatientExperience()]);setData(dashboard);setCatalog(booking);setCare(careHub);setMembership(membershipCard);setResults(patientResults);setBeauty(beautyCalendar);setFinance(financeHealth);setExperience(patientExperience);}catch(e){setError(e instanceof Error?e.message:"Unable to load your account");}},[]);
  useEffect(()=>{supabase.auth.getSession().then(({data})=>{setAuthenticated(Boolean(data.session));setSessionReady(true);if(data.session)setTimeout(refresh,0);});const{data:listener}=supabase.auth.onAuthStateChange((_event,session)=>{setAuthenticated(Boolean(session));if(session)setTimeout(refresh,0);else setData(null);});return()=>listener.subscription.unsubscribe();},[refresh]);
  useEffect(()=>{void AsyncStorage.getItem("zernio_language").then(value=>{if(value==="ar"||value==="en")setLanguage(value);});},[]);
  useEffect(()=>{if(!authenticated)return;const channel=supabase.channel("patient-notification-updates").on("postgres_changes",{event:"INSERT",schema:"public",table:"patient_notifications"},()=>{void refresh();}).subscribe();return()=>{void supabase.removeChannel(channel);};},[authenticated,refresh]);
  useEffect(()=>{if(!authenticated)return;const timer=setInterval(()=>void refresh(),10000);const listener=AppState.addEventListener("change",state=>{if(state==="active")void refresh();});return()=>{clearInterval(timer);listener.remove();};},[authenticated,refresh]);
  const toggleLanguage=()=>{const next=language==="en"?"ar":"en";setLanguage(next);void AsyncStorage.setItem("zernio_language",next);};
  if(!sessionReady) return <SafeAreaProvider><View style={s.loader}><Image alt="Panthera Clinics" source={pantheraBrand} style={{width:280,height:180}} resizeMode="contain"/><Text style={s.cardMuted}>{language==="ar"?"جارٍ التحميل بأمان…":"Loading securely…"}</Text></View></SafeAreaProvider>;
  if(!authenticated) return <SafeAreaProvider><StatusBar style="dark"/><Login language={language} toggleLanguage={toggleLanguage}/></SafeAreaProvider>;
  if(!data) return <SafeAreaProvider><View style={s.loader}><Image alt="Panthera Clinics" source={pantheraBrand} style={{width:280,height:180}} resizeMode="contain"/><Text style={s.cardMuted}>{error||(language==="ar"?"جارٍ تحميل بياناتك…":"Loading your care…")}</Text>{error?<TouchableOpacity style={s.secondary} onPress={refresh}><Text style={s.secondaryText}>{language==="ar"?"حاول مرة أخرى":"Try again"}</Text></TouchableOpacity>:null}</View></SafeAreaProvider>;
  const main = tab==="home"?<Home go={setTab} data={data} catalog={catalog} language={language}/>:tab==="book"?<Booking refresh={refresh} language={language}/>:tab==="care"?<Care data={care} language={language}/>:tab==="appointments"?<Appointments data={data.appointments} language={language}/>:tab==="medical"?<HealthCenter data={finance.health} language={language} refresh={refresh} back={()=>setTab("profile")}/>:tab==="wallet"?<Wallet data={finance.wallet} language={language} back={()=>setTab("profile")}/>:tab==="membership"?<Membership data={membership} language={language} back={()=>setTab("profile")}/>:tab==="results"?<Results data={results} language={language} go={setTab} back={()=>setTab("profile")}/>:tab==="beauty"?<BeautyCalendar data={beauty} language={language} back={()=>setTab("profile")}/>:tab==="experience"?<Experience data={experience} language={language} refresh={refresh} back={()=>setTab("profile")}/>:tab==="support"?<Support data={beauty.contact} language={language} back={()=>setTab("home")}/>:tab==="notifications"?<Notifications data={data.notifications} language={language} back={()=>setTab("home")}/>:<Profile data={data} go={setTab} language={language} toggleLanguage={toggleLanguage} logout={()=>supabase.auth.signOut()}/>;
  const toolbarButton={minWidth:48,height:42,paddingHorizontal:12,borderRadius:14,backgroundColor:"#fff",borderWidth:1,borderColor:colors.border,alignItems:"center" as const,justifyContent:"center" as const,flexDirection:"row" as const,gap:4,shadowColor:"#000",shadowOpacity:.08,shadowRadius:10,shadowOffset:{width:0,height:4}},t=translate(language),homeToolbar=tab==="home"?<Animated.View style={{position:"absolute",top:18,right:18,flexDirection:"row",gap:8,zIndex:20,opacity:toolbarOpacity}}><TouchableOpacity style={toolbarButton} onPress={()=>setTab("notifications")}><Icon name="notifications-outline" color={colors.violet}/>{data.notifications.some(x=>!x.is_read)?<View style={{position:"absolute",right:7,top:7,width:8,height:8,borderRadius:4,backgroundColor:colors.danger,borderWidth:1,borderColor:"#fff"}}/>:null}</TouchableOpacity><TouchableOpacity style={toolbarButton} onPress={toggleLanguage}><Text style={{fontSize:12,fontWeight:"900",color:colors.text}}>{language==="ar"?"EN":"عربي"}</Text></TouchableOpacity></Animated.View>:null;return <SafeAreaProvider><SafeAreaView style={s.safe}><StatusBar style="dark"/><View style={s.content} onTouchMove={fadeToolbar}>{main}{homeToolbar}</View>{tab!=="support"?<TouchableOpacity accessibilityLabel={language==="ar"?"المساعدة":"Help"} onPress={()=>setTab("support")} style={{position:"absolute",right:22,bottom:94,width:54,height:54,borderRadius:20,backgroundColor:colors.navy,alignItems:"center",justifyContent:"center",shadowColor:colors.ink,shadowOpacity:.28,shadowRadius:14,shadowOffset:{width:0,height:8},zIndex:30}}><Icon name="chatbubble-ellipses" color="#fff" size={25}/></TouchableOpacity>:null}<View style={s.nav}>{[["home","home",t.home],["book","add-circle",t.book],["care","heart",language==="ar"?"رحلتي":"My care"],["appointments","calendar",t.visits],["profile","person",t.profile]].map(([id,icon,label])=><TouchableOpacity key={id} style={s.navItem} onPress={()=>setTab(id as Tab)}><Icon name={(tab===id?icon:`${icon}-outline`) as IconName} color={tab===id?"#FFFFFF":"#AEBBC2"}/><Text style={[s.navText,tab===id&&s.navActive]}>{label}</Text></TouchableOpacity>)}</View></SafeAreaView></SafeAreaProvider>;
}

